tracks = {}  # Persistent across all frames: id -> {box,score,class,label,missed}
next_id = 1

def iou(a, b):
    ix1, iy1 = max(a[0], b[0]), max(a[1], b[1])
    ix2, iy2 = min(a[2], b[2]), min(a[3], b[3])
    intersection = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
    area_a = max(0.0, a[2] - a[0]) * max(0.0, a[3] - a[1])
    area_b = max(0.0, b[2] - b[0]) * max(0.0, b[3] - b[1])
    union = area_a + area_b - intersection
    return intersection / union if union > 0 else 0.0

def process(detections, meta):
    global next_id
    candidates = []
    for track_id, track in tracks.items():
        for j, det in enumerate(detections):
            if track['class'] == det['class']:
                overlap = iou(track['box'], det['box'])
                if overlap >= 0.3: candidates.append((overlap, track_id, j))
    matched_ids, matched_dets = set(), set()
    for overlap, track_id, j in sorted(candidates, key=lambda item: (-item[0], item[1], item[2])):
        if track_id in matched_ids or j in matched_dets: continue
        det = detections[j]
        tracks[track_id].update(box=det['box'], score=det['score'], missed=0)
        matched_ids.add(track_id)
        matched_dets.add(j)
    for track_id in list(tracks):
        if track_id not in matched_ids:
            tracks[track_id]['missed'] += 1
            if tracks[track_id]['missed'] > 30: del tracks[track_id]
    current = []
    for j, det in enumerate(detections):
        if j not in matched_dets:
            track_id = next_id
            next_id += 1
            tracks[track_id] = {**det, 'missed': 0}
        else:
            track_id = next(tid for tid in matched_ids if tracks[tid]['missed'] == 0 and tid in [candidate_id for _, candidate_id, candidate_j in candidates if candidate_j == j and candidate_id in matched_ids and tracks[candidate_id]['box'] == det['box']])
        current.append({'track_id': track_id, 'box': list(det['box']), 'score': det['score'], 'class': det['class'], 'label': det['label']})
    return {'frame_index': meta['frame_index'], 'timestamp_s': meta['timestamp_s'], 'tracks': current}
